(7010042, 1060222, 158576, '<td valign="top">Great exposure and very crisp. The buildings are very unique and have a kind of abstractness to them.</td>', 'Great exposure and very crisp. The buildings are very unique and have a kind of abstractness to them.', '2013-03-31 12:35:39.000000', NULL, 1),
(7010045, 1059272, 113156, '<td valign="top">Needed done, glad you caught it.</td>', 'Needed done, glad you caught it.', '2013-03-31 12:37:38.000000', NULL, 1),
