(7010050, 1060166, 158576, '<td valign="top">There''s something about the sky that seems a bit "off", otherwise the bridge and it''s "holes" really catch your eye.</td>', 'There''s something about the sky that seems a bit "off", otherwise the bridge and it''s "holes" really catch your eye.', '2013-03-31 12:44:55.000000', NULL, 1),
(7010051, 1060360, 158576, '<td valign="top">There''s something almost sinister about some of those dolls. I can see them as part of a nightmarish scene in a Tim Burton film.</td>', 'There''s something almost sinister about some of those dolls. I can see them as part of a nightmarish scene in a Tim Burton film.', '2013-03-31 12:47:12.000000', NULL, 1),
(7010053, 1059775, 158576, '<td valign="top">I don''t know, maybe it the symmetry, maybe it''s the way the eye is lead, but something makes this really hard to tear your eyes away from it.</td>', 'I don''t know, maybe it the symmetry, maybe it''s the way the eye is lead, but something makes this really hard to tear your eyes away from it.', '2013-03-31 12:50:01.000000', NULL, 1),
(7010054, 1060348, 158576, '<td valign="top">Great color, shadows, and composition.</td>', 'Great color, shadows, and composition.', '2013-03-31 12:51:05.000000', NULL, 1),
(7010055, 1059385, 158576, '<td valign="top">Very stark and dramatic. Reminds me of scenes from movies where the POV is from the guy on the guerny being pushed down the hospital hall and all you can see are the overhead lights moving by.</td>', 'Very stark and dramatic. Reminds me of scenes from movies where the POV is from the guy on the guerny being pushed down the hospital hall and all you can see are the overhead lights moving by.', '2013-03-31 12:53:41.000000', NULL, 1),
(7010058, 1060133, 158576, '<td valign="top">The billowing snow changes this shot from an ordinary winter landscape to something dramatic and extraordianry. You can almost feel the wind and the cold.</td>', 'The billowing snow changes this shot from an ordinary winter landscape to something dramatic and extraordianry. You can almost feel the wind and the cold.', '2013-03-31 12:59:19.000000', NULL, 1),
(7010060, 1059730, 158576, '<td valign="top">Very retro feel to this scene.</td>', 'Very retro feel to this scene.', '2013-03-31 13:02:15.000000', NULL, 1),
(7010063, 1059943, 158576, '<td valign="top">Great street photography. A definate decisive moment.</td>', 'Great street photography. A definate decisive moment.', '2013-03-31 13:03:35.000000', NULL, 1),
(7010065, 1059912, 158576, '<td valign="top">It meets the challenge, but the quality of the shot is low.</td>', 'It meets the challenge, but the quality of the shot is low.', '2013-03-31 13:06:34.000000', NULL, 1),
(7010067, 1059581, 158576, '<td valign="top">Nice shot. If it weren''t for the modern looking graffit, this could pass for a scene from the 50''s or 60''s. Very retro in a way that brings a feeling of nostalgia.</td>', 'Nice shot. If it weren''t for the modern looking graffit, this could pass for a scene from the 50''s or 60''s. Very retro in a way that brings a feeling of nostalgia.', '2013-03-31 13:08:36.000000', NULL, 1),
(7010069, 1060109, 158576, '<td valign="top">Interesting looking game, very retro looking.</td>', 'Interesting looking game, very retro looking.', '2013-03-31 13:09:44.000000', NULL, 1),
(7010070, 1059829, 158576, '<td valign="top">It doesn''t "pop", the low contrast makes it see a bit "flat", and although it meets the challenge, it''s a bit too "greeting cardish" for my taste.</td>', 'It doesn''t "pop", the low contrast makes it see a bit "flat", and although it meets the challenge, it''s a bit too "greeting cardish" for my taste.', '2013-03-31 13:12:49.000000', NULL, 1),
